import warnings
import os
import glob
import shutil
import time

def task_func(SOURCE_DIR, DEST_DIR, EXTENSIONS):
    transferred_files = []

    if not os.path.isdir(SOURCE_DIR):
        warnings.warn(f"SOURCE_DIR '{SOURCE_DIR}' does not exist.")
        return transferred_files

    if not os.path.isdir(DEST_DIR):
        try:
            os.makedirs(DEST_DIR)
        except Exception as e:
            warnings.warn(f"Could not create DEST_DIR '{DEST_DIR}': {e}")
            return transferred_files

    for ext in EXTENSIONS:
        pattern = os.path.join(SOURCE_DIR, f"*{ext}")
        files = glob.glob(pattern)

        for file in files:
            try:
                shutil.copy2(file, DEST_DIR)
                transferred_files.append(os.path.basename(file))
            except Exception as e:
                warnings.warn(f"Could not transfer file '{file}': {e}")

    return transferred_files

import pandas as pd
import random
from datetime import datetime

def task_func(
    task_list,
    n_tasks,
    employees=["John Doe", "Jane Smith", "James Brown", "Mary Johnson", "Robert Davis"],
    seed=None,
):
    if n_tasks < 0:
        raise ValueError("n_tasks must be non-negative")

    if seed is not None:
        random.seed(seed)

    if n_tasks > len(task_list):
        raise ValueError("n_tasks cannot exceed the number of tasks in task_list")

    selected_tasks = random.sample(task_list, n_tasks)
    current_date = datetime.now().strftime("%Y-%m-%d")

    rows = []
    for task in selected_tasks:
        sanitized_task = task.replace(" ", "_")
        assigned_to = random.choice(employees)
        rows.append({
            "Task Name": sanitized_task,
            "Assigned To": assigned_to,
            "Due Date": current_date
        })

    return pd.DataFrame(rows)

import pandas as pd
from datetime import datetime
import random

def task_func(
    epoch_milliseconds,
    random_seed=0,
    products=["Product1", "Product2", "Product3", "Product4", "Product5"],
):
    if not isinstance(epoch_milliseconds, (int, float)):
        raise TypeError("epoch_milliseconds must be a number")
    if epoch_milliseconds < 0:
        raise ValueError("epoch_milliseconds must be non-negative")
    if not isinstance(random_seed, int):
        raise TypeError("random_seed must be an integer")
    if not isinstance(products, list) or len(products) != 5:
        raise ValueError("products must be a list of exactly 5 items")

    random.seed(random_seed)

    start_date = datetime.fromtimestamp(epoch_milliseconds / 1000).date()
    end_date = datetime.now().date()

    if start_date > end_date:
        raise ValueError("epoch_milliseconds must be in the past")

    dates = []
    current_date = start_date
    while current_date <= end_date:
        dates.append(current_date)
        current_date += pd.Timestamp('1D').date()

    data = []
    for date in dates:
        for product in products:
            sales = random.randint(10, 50)
            data.append({
                'Product': product,
                'Date': date,
                'Sales': sales
            })

    df = pd.DataFrame(data)
    return df
